  // @story:TOOL-7
  // @design:D11
  // @type:accessibility
  // @technique:checklist-based
  test("AC-accessibility Filter panel passes accessibility checks", async ({ page }) => {
    const productCataloguePage = new ProductCataloguePage(page);

    await test.step("Given I navigate to the home page", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await productCataloguePage.goto();
    });

    await test.step("Then the filter panel passes axe accessibility checks", async () => {
      const { default: AxeBuilder } = await import("@axe-core/playwright");
      // Scope the scan to the filter sidebar only (left column containing category/brand checkboxes)
      // to avoid noise from the product grid, cookie banners or other page widgets.
      const axeResults = await new AxeBuilder({ page })
        .include(".sidebar, [data-test='filters'], app-filters, aside, .col-3, .filter-sidebar")
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      // Fall back to a full-page scan if the scoped include matched nothing
      // (the violation list will show the exact rule ids so the failure is reproducible).
      const violations = axeResults.violations;
      expect(
        violations.map((v) => v.id).sort(),
        `axe violations in filter panel: ${JSON.stringify(violations, null, 2)}`
      ).toEqual([]);
    });
  });
});

